create table if not exists app.generated_artifacts (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, application_id uuid references app.applications(id) on delete cascade, artifact_type text not null, title text not null, current_version_id uuid, created_at timestamptz not null default now());
create table if not exists app.artifact_versions (id uuid primary key default gen_random_uuid(), artifact_id uuid not null references app.generated_artifacts(id) on delete cascade, version integer not null, status text not null default 'draft', storage_key text, media_type text, binary_hash text, content_manifest_hash text, renderer_version text, evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now(), unique (artifact_id, version));
create table if not exists app.application_packages (id uuid primary key default gen_random_uuid(), application_id uuid not null references app.applications(id) on delete cascade, version integer not null, status text not null default 'draft', manifest_hash text not null, created_at timestamptz not null default now(), reviewed_at timestamptz, submitted_at timestamptz, unique (application_id, version));
create table if not exists app.application_package_items (package_id uuid not null references app.application_packages(id) on delete cascade, artifact_version_id uuid references app.artifact_versions(id), item_type text not null, display_order integer not null default 0, required boolean not null default false, primary key (package_id, item_type, display_order));
alter table app.applications enable row level security; alter table app.generated_artifacts enable row level security; alter table app.application_documents enable row level security;
create policy applications_owner on app.applications for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy artifacts_owner on app.generated_artifacts for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy application_documents_owner on app.application_documents for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
